import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

hardtanh_kernel_code = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void hardtanh_kernel(const float* input, float* output, int num_elements) {
    const int index = blockIdx.x * blockDim.x + threadIdx.x;
    if (index < num_elements) {
        float value = input[index];
        output[index] = fminf(fmaxf(value, -1.0f), 1.0f);
    }
}

torch::Tensor hardtanh_cuda_forward(torch::Tensor input) {
    torch::Tensor output = torch::empty_like(input);

    int num_elements = input.numel();
    const int threads_per_block = 256;
    const int num_blocks = (num_elements + threads_per_block - 1) / threads_per_block;

    hardtanh_kernel<<<num_blocks, threads_per_block>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        num_elements
    );

    return output;
}
"""

hardtanh_cpp_code = "torch::Tensor hardtanh_cuda_forward(torch::Tensor input);"

hardtanh_extension = load_inline(
    name='hardtanh_extension',
    cpp_sources=hardtanh_cpp_code,
    cuda_sources=hardtanh_kernel_code,
    functions=['hardtanh_cuda_forward'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.hardtanh_op = hardtanh_extension.hardtanh_cuda_forward

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.hardtanh_op(x)
